 * the real JSON exactly.
 * ---
 * Manifiesto de versión publicado junto al APK en cada Release de
 * miA2FReleases (lo genera build-and-deploy.yml). Los nombres de campo
 * deben coincidir exactamente con el JSON real.
 */
data class UpdateManifest(
